1	<?php
2	
3	namespace App\Jobs\Shopify;
4	
5	use App\Models\Core\Professional\BrandPartnerLink;
6	use App\Models\Core\Professional\Professional;
7	use App\Models\Core\Professional\ProfessionalIntegration;
8	use App\Models\Retail\BrandStoreSettings;
9	use App\Models\Retail\CommissionLedgerEntry;
10	use App\Services\Customers\ContactCaptureService;
11	use App\Services\Store\BrandCatalogService;
12	use Illuminate\Bus\Queueable;
13	use Illuminate\Contracts\Queue\ShouldQueue;
14	use Illuminate\Foundation\Bus\Dispatchable;
15	use Illuminate\Queue\InteractsWithQueue;
16	use Illuminate\Queue\SerializesModels;
17	use Illuminate\Support\Arr;
18	use Illuminate\Support\Carbon;
19	use Illuminate\Support\Facades\DB;
20	use Illuminate\Support\Facades\Log;
21	
22	// V2: Processes a Shopify orders/paid webhook — identifies affiliate, calculates commission, creates ledger entries, and captures the customer as an affiliate contact.
23	class ProcessShopifyOrderWebhookJob implements ShouldQueue
24	{
25	    use Dispatchable, InteractsWithQueue, Queueable, SerializesModels;
26	
27	    public int $tries = 3;
28	
29	    public int $timeout = 30;
30	
31	    public function __construct(
32	        public string $brandProfessionalId,
33	        public array $orderPayload,
34	    ) {
35	        $this->onQueue('integrations');
36	    }
37	
38	    public function handle(ContactCaptureService $contactCapture, BrandCatalogService $catalogService): void
39	    {
40	        $orderId = (string) Arr::get($this->orderPayload, 'id', '');
41	        $noteAttributes = Arr::get($this->orderPayload, 'note_attributes', []);
42	        $lineItems = Arr::get($this->orderPayload, 'line_items', []);
43	        $currency = strtoupper(trim((string) Arr::get($this->orderPayload, 'currency', 'AUD')));
44	        $occurredAt = Arr::get($this->orderPayload, 'created_at', now()->toIso8601String());
45	
46	        // Extract affiliate slug from cart attributes
47	        $affiliateSlug = $this->extractCartAttribute($noteAttributes, 'affiliate');
48	
49	        if ($affiliateSlug === '') {
50	            Log::info('Shopify order webhook: no affiliate attribute, skipping', [
51	                'order_id' => $orderId,
52	                'brand_professional_id' => $this->brandProfessionalId,
53	            ]);
54	
55	            return;
56	        }
57	
58	        // Look up affiliate
59	        $affiliate = Professional::query()
60	            ->where('handle_lc', strtolower($affiliateSlug))
61	            ->first();
62	
63	        if (! $affiliate) {
64	            Log::warning('Shopify order webhook: affiliate not found', [
65	                'order_id' => $orderId,
66	                'affiliate_slug' => $affiliateSlug,
67	            ]);
68	
69	            return;
70	        }
71	
72	        // Verify affiliate is connected to this brand
73	        $isConnected = BrandPartnerLink::query()
74	            ->where('affiliate_professional_id', $affiliate->id)
75	            ->where('brand_professional_id', $this->brandProfessionalId)
76	            ->exists();
77	
78	        if (! $isConnected) {
79	            Log::warning('Shopify order webhook: affiliate not connected to brand', [
80	                'order_id' => $orderId,
81	                'affiliate_id' => (string) $affiliate->id,
82	                'brand_professional_id' => $this->brandProfessionalId,
83	            ]);
84	
85	            return;
86	        }
87	
88	        // Get brand settings and platform fallback for server-side rate resolution.
89	        $brandSettings = BrandStoreSettings::where('professional_id', $this->brandProfessionalId)->first();
90	        $platformDefault = (float) config('sidest.store.default_commission_rate', 15);
91	
92	        // Collect distinct product GIDs from the order's line items. Shopify
93	        // sends a numeric product_id on the REST webhook payload; convert to GID
94	        // shape so we can query the Admin API (which only accepts GIDs via nodes()).
95	        $productGids = [];
96	        foreach ($lineItems as $li) {
97	            if (! is_array($li)) {
98	                continue;
99	            }
100	            $productId = (string) Arr::get($li, 'product_id', '');
101	            if ($productId !== '') {
102	                $productGids[] = "gid://shopify/Product/{$productId}";
103	            }
104	        }
105	        $productGids = array_values(array_unique($productGids));
106	
107	        // Fetch commission_override metafield for each product in ONE Admin API
108	        // call. Buyer-set sidest_commission_rate line attributes are NOT used for
109	        // calculation — they're writable by the buyer via the Storefront Cart API
110	        // and therefore untrusted. We resolve the rate ourselves using the same
111	        // precedence the Hydrogen storefront applies.
112	        $integration = ProfessionalIntegration::query()
113	            ->where('professional_id', $this->brandProfessionalId)
114	            ->where('provider', ProfessionalIntegration::PROVIDER_SHOPIFY)
115	            ->first();
116	
117	        // Validate order currency against shop_currency stored in integration metadata.
118	        // Mismatches (e.g. a multi-currency store misconfiguration) mean commission math
119	        // would be in the wrong unit — skip and log rather than create wrong ledger entries.
120	        $shopCurrency = strtoupper(trim((string) Arr::get($integration?->provider_metadata ?? [], 'shop_currency', '')));
121	        if ($shopCurrency !== '' && $shopCurrency !== $currency) {
122	            Log::warning('Shopify order webhook: currency mismatch, skipping commission', [
123	                'order_id' => $orderId,
124	                'brand_professional_id' => $this->brandProfessionalId,
125	                'order_currency' => $currency,
126	                'shop_currency' => $shopCurrency,
127	            ]);
128	
129	            return;
130	        }
131	
132	        $overrideMap = ($integration && ! empty($productGids))
133	            ? $catalogService->fetchCommissionOverridesForProducts($integration, $productGids)
134	            : [];
135	
136	        // Phase 1: build candidates without touching the DB
137	        $candidates = [];
138	        foreach ($lineItems as $lineItem) {
139	            if (! is_array($lineItem)) {
140	                continue;
141	            }
142	
143	            $lineItemId = (string) Arr::get($lineItem, 'id', '');
144	            $unitPrice = (float) Arr::get($lineItem, 'price', 0);
145	            $quantity = (int) Arr::get($lineItem, 'quantity', 1);
146	
147	            if ($lineItemId === '' || $unitPrice <= 0 || $quantity <= 0) {
148	                continue;
149	            }
150	
151	            // Commission base = what the customer actually paid for this line
152	            // (post-discount). Shopify's orders/paid webhook line_items shape:
153	            //   price             — pre-discount unit price
154	            //   quantity          — units in the line
155	            //   total_discount    — sum of every discount allocation applied to this line
156	            //                       (Side St Price Function discount included)
157	            //   discount_allocations[] — per-allocation breakdown (not needed here,
158	            //       but worth knowing if we ever need to differentiate our function
159	            //       from a manually-applied code on the same line).
160	            //
161	            // Using post-discount line total keeps commission aligned with the
162	            // brand's actual revenue on the sale — a 20% Side St Price discount
163	            // means the brand took home 20% less, and the affiliate's commission
164	            // on that line is 20% smaller too at the same commission rate.
165	            $lineTotalPreDiscount = $unitPrice * $quantity;
166	            $totalDiscount = (float) Arr::get($lineItem, 'total_discount', 0);
167	            $lineTotal = max(0.0, $lineTotalPreDiscount - $totalDiscount);
168	
169	            if ($lineTotal <= 0) {
170	                // Line fully discounted (100% off, comp, etc.) — nothing to
171	                // accrue. Skip rather than emit a zero-cent entry.
172	                continue;
173	            }
174	
175	            $productGid = ($productIdStr = (string) Arr::get($lineItem, 'product_id', '')) !== ''
176	                ? "gid://shopify/Product/{$productIdStr}"
177	                : '';
178	
179	            [$commissionRate, $rateSource] = $this->resolveCommissionRate(
180	                $productGid,
181	                $overrideMap,
182	                $brandSettings,
183	                $platformDefault,
184	            );
185	
186	            $commissionAmountCents = (int) round($lineTotal * ($commissionRate / 100) * 100);
187	
188	            if ($commissionAmountCents <= 0) {
189	                continue;
190	            }
191	
192	            // Audit trail: the buyer-submitted rate (may be empty or inflated).
193	            // Recorded verbatim so post-hoc investigations can detect tampering.
194	            $submittedRate = $this->extractSubmittedRate($lineItem);
195	
196	            $candidates[] = [
197	                'idempotency_key' => "shopify_order_{$orderId}_line_{$lineItemId}",
198	                'data' => [
199	                    'shopify_order_id' => $orderId,
200	                    'brand_professional_id' => $this->brandProfessionalId,
201	                    'affiliate_professional_id' => (string) $affiliate->id,
202	                    'entry_type' => 'accrual',
203	                    'status' => 'approved',
204	                    'amount_cents' => $commissionAmountCents,
205	                    'currency_code' => $currency,
206	                    'commission_rate' => $commissionRate,
207	                    'rate_source' => $rateSource,
208	                    'idempotency_key' => "shopify_order_{$orderId}_line_{$lineItemId}",
209	                    'calculation_metadata' => [
210	                        'order_id' => $orderId,
211	                        'line_item_id' => $lineItemId,
212	                        'product_id' => (string) Arr::get($lineItem, 'product_id', ''),
213	                        // Captured here because Shopify only populates `title` on
214	                        // the order/line payload — fetching it later would need an
215	                        // Admin API roundtrip per row. Powers the "Top Products"
216	                        // analytics widget.
217	                        'product_title' => (string) Arr::get($lineItem, 'title', ''),
218	                        // Keep both for audit: pre-discount line price (what the
219	                        // Shopify sticker was) plus the discount applied by
220	                        // any function/code, plus the post-discount figure we
221	                        // computed commission off.
222	                        'unit_price' => $unitPrice,
223	                        'line_price_pre_discount' => $lineTotalPreDiscount,
224	                        'total_discount' => $totalDiscount,
225	                        'line_price_post_discount' => $lineTotal,
226	                        'quantity' => $quantity,
227	                        'affiliate_slug' => $affiliateSlug,
228	                        'submitted_rate' => $submittedRate,
229	                    ],
230	                    'occurred_at' => $occurredAt,
231	                ],
232	            ];
233	        }
234	
235	        // Phase 2: pre-filter existing idempotency keys (one query), then bulk-insert in one transaction.
236	        // Pre-filtering avoids a 23505 unique violation inside the transaction — PostgreSQL aborts the
237	        // entire transaction on constraint violations, so we can't catch-and-continue inside DB::transaction().
238	        $entriesCreated = 0;
239	        if (! empty($candidates)) {
240	            $candidateKeys = array_column($candidates, 'idempotency_key');
241	            $existingKeys = CommissionLedgerEntry::whereIn('idempotency_key', $candidateKeys)
242	                ->pluck('idempotency_key')
243	                ->flip()
244	                ->all();
245	
246	            $newEntries = array_filter($candidates, fn ($c) => ! isset($existingKeys[$c['idempotency_key']]));
247	
248	            DB::transaction(function () use ($newEntries, $affiliate, &$entriesCreated): void {
249	                foreach ($newEntries as $entry) {
250	                    // Preload the relation before save so the observer's notifyBrandSale()
251	                    // can access affiliateProfessional->display_name without a lazy query.
252	                    // The pre-set survives the observer's afterCommit dispatch — Laravel
253	                    // keeps object identity (no clone) for synchronous post-commit callbacks.
254	                    $row = new CommissionLedgerEntry($entry['data']);
255	                    $row->setRelation('affiliateProfessional', $affiliate);
256	                    $row->save();
257	                    $entriesCreated++;
258	                }
259	            });
260	        }
261	
262	        // Capture the buyer as an affiliate contact (Beta 3 — Contacts — Automatic Customer Capture).
263	        // Non-blocking: any failure inside the service is logged and swallowed so it can never
264	        // fail commission processing above.
265	        $this->captureAffiliateContact($contactCapture, (string) $affiliate->id, $noteAttributes, $orderId);
266	
267	        // Rebuild commerce daily aggregates so dashboards and weekly notifications
268	        // reflect this order. Non-blocking — queued on the analytics worker.
269	        if ($entriesCreated > 0) {
270	            \App\Jobs\Analytics\RebuildCommerceDailyAggregatesJob::dispatch(
271	                $this->brandProfessionalId,
272	                (string) $affiliate->id,
273	                Carbon::parse($occurredAt)->toDateString()
274	            );
275	            \App\Jobs\Analytics\RebuildCommerceHourlyAggregatesJob::dispatch(
276	                $this->brandProfessionalId,
277	                (string) $affiliate->id,
278	                Carbon::parse($occurredAt)->utc()->startOfHour()->toIso8601String()
279	            );
280	        }
281	
282	        Log::info('Shopify order webhook processed', [
283	            'order_id' => $orderId,
284	            'brand_professional_id' => $this->brandProfessionalId,
285	            'affiliate_id' => (string) $affiliate->id,
286	            'entries_created' => $entriesCreated,
287	        ]);
288	    }
289	
290	    /**
291	     * Upsert the buyer into the affiliate's contacts list and, if the cart
292	     * carried a truthy `sidest_marketing_opt_in` attribute, add them to the
293	     * affiliate's marketing subscribers.
294	     *
295	     * Name resolution priority (matches the commit message): try
296	     * billing_address.name first (Shopify populates this with the full name
297	     * as entered at checkout), then fall back to customer.first_name +
298	     * customer.last_name from the Shopify customer record.
299	     *
300	     * @param  array<int, array<string, mixed>>|mixed  $noteAttributes
301	     */
302	    private function captureAffiliateContact(
303	        ContactCaptureService $contactCapture,
304	        string $affiliateId,
305	        mixed $noteAttributes,
306	        string $orderId,
307	    ): void {
308	        $customer = Arr::get($this->orderPayload, 'customer', []);
309	        $billingAddress = Arr::get($this->orderPayload, 'billing_address', []);
310	
311	        $email = trim((string) Arr::get($customer, 'email', ''));
312	        if ($email === '') {
313	            // Shopify guest checkouts or POS orders without a customer — nothing to capture.
314	            return;
315	        }
316	
317	        // Name: prefer billing_address.name, then fall back to customer first/last.
318	        $billingName = trim((string) Arr::get($billingAddress, 'name', ''));
319	        $firstName = trim((string) Arr::get($customer, 'first_name', ''));
320	        $lastName = trim((string) Arr::get($customer, 'last_name', ''));
321	        $fullName = $billingName !== '' ? $billingName : trim($firstName.' '.$lastName);
322	        $fullName = $fullName !== '' ? $fullName : null;
323	
324	        $marketingConsent = $this->parseMarketingOptInAttribute($noteAttributes);
325	
326	        // ContactCaptureService normalizes phone/full_name null-or-empty — we
327	        // can pass raw values through without pre-guarding.
328	        $contactCapture->captureContact($affiliateId, [
329	            'email' => $email,
330	            'full_name' => $fullName,
331	            'phone' => (string) Arr::get($billingAddress, 'phone', ''),
332	            'source' => 'shopify_order',
333	            'external_id' => $orderId !== '' ? $orderId : null,
334	            // Only override the service default when the shopper EXPLICITLY opted out.
335	            // Missing attribute -> null -> service default (true). Explicit "true" is
336	            // also null here because captureMarketingSubscription() handles it below.
337	            'marketing_opt_in' => $marketingConsent === false ? false : null,
338	        ]);
339	
340	        // Truthy consent -> add them to the marketing list. Missing/falsy: the
341	        // contact is still captured above, just not subscribed for email blasts.
342	        if ($marketingConsent === true) {
343	            $contactCapture->captureMarketingSubscription(
344	                $affiliateId,
345	                $email,
346	                $fullName,
347	                'shopify_order',
348	            );
349	        }
350	    }
351	
352	    /**
353	     * Parse the `sidest_marketing_opt_in` cart attribute into an explicit
354	     * tri-state: true (explicit opt-in), false (explicit opt-out), or null
355	     * (attribute missing / unrecognized value — let the schema default apply).
356	     *
357	     * Hydrogen is the only documented producer of this attribute. Recognized
358	     * values (case-insensitive):
359	     *   truthy:  'true' | '1' | 'yes'
360	     *   falsy:   'false' | '0' | 'no'
361	     *
362	     * Any other string is treated as "missing" so a typo doesn't silently
363	     * flip consent to false.
364	     *
365	     * @param  array<int, array<string, mixed>>|mixed  $noteAttributes
366	     */
367	    private function parseMarketingOptInAttribute(mixed $noteAttributes): ?bool
368	    {
369	        $raw = strtolower($this->extractCartAttribute($noteAttributes, 'sidest_marketing_opt_in'));
370	        if ($raw === '') {
371	            return null;
372	        }
373	        if (in_array($raw, ['true', '1', 'yes'], true)) {
374	            return true;
375	        }
376	        if (in_array($raw, ['false', '0', 'no'], true)) {
377	            return false;
378	        }
379	
380	        return null;
381	    }
382	
383	    /**
384	     * Extract a value from Shopify note_attributes (cart-level attributes).
385	     */
386	    private function extractCartAttribute(mixed $noteAttributes, string $key): string
387	    {
388	        if (! is_array($noteAttributes)) {
389	            return '';
390	        }
391	
392	        foreach ($noteAttributes as $attr) {
393	            if (is_array($attr) && strtolower(trim((string) ($attr['name'] ?? ''))) === $key) {
394	                return trim((string) ($attr['value'] ?? ''));
395	            }
396	        }
397	
398	        return '';
399	    }
400	
401	    /**
402	     * Resolve the commission rate for a line item, server-side. Precedence:
403	     *   1. product metafield `sidest.commission_override` (brand-set per-product)
404	     *   2. brand.brand_store_settings.default_commission_rate (brand default)
405	     *   3. config('sidest.store.default_commission_rate', 15) (platform fallback)
406	     *
407	     * @param  array<string, float|null>  $overrideMap
408	     * @return array{0: float, 1: string} [rate, rate_source]
409	     */
410	    private function resolveCommissionRate(
411	        string $productGid,
412	        array $overrideMap,
413	        ?BrandStoreSettings $brandSettings,
414	        float $platformDefault,
415	    ): array {
416	        if ($productGid !== '' && isset($overrideMap[$productGid]) && $overrideMap[$productGid] !== null) {
417	            $rate = (float) $overrideMap[$productGid];
418	            if ($rate > 0 && $rate <= 100) {
419	                return [$rate, 'metafield_override'];
420	            }
421	        }
422	
423	        if ($brandSettings && $brandSettings->default_commission_rate !== null) {
424	            return [(float) $brandSettings->default_commission_rate, 'brand_default'];
425	        }
426	
427	        return [$platformDefault, 'platform_default'];
428	    }
429	
430	    /**
431	     * Pull the buyer-submitted sidest_commission_rate for the audit trail.
432	     * NOT used for calculation — returned verbatim so post-hoc analysis can
433	     * spot cart tampering or Hydrogen/webhook drift.
434	     */
435	    private function extractSubmittedRate(array $lineItem): ?string
436	    {
437	        $properties = Arr::get($lineItem, 'properties', []);
438	        if (! is_array($properties)) {
439	            return null;
440	        }
441	        foreach ($properties as $prop) {
442	            if (is_array($prop) && strtolower(trim((string) ($prop['name'] ?? ''))) === 'sidest_commission_rate') {
443	                return (string) ($prop['value'] ?? '');
444	            }
445	        }
446	
447	        return null;
448	    }
449	}
