3	namespace App\Services\Stripe;
4	
5	use App\Jobs\Stripe\ExecuteCommissionPayoutJob;
6	use App\Models\Core\Professional\Professional;
7	use App\Models\Retail\BrandStoreSettings;
8	use App\Models\Retail\CommissionLedgerEntry;
9	use App\Models\Retail\CommissionPayout;
10	use App\Models\Retail\CommissionPayoutItem;
11	use Illuminate\Support\Facades\DB;
12	use Illuminate\Support\Facades\Log;
13	use Stripe\Exception\ApiConnectionException;
14	use Stripe\Exception\ApiErrorException;
15	use Stripe\Exception\RateLimitException;
16	use Stripe\StripeClient;
17	
18	// V2: Core. Processes eligible commission payouts with hybrid funding (wallet balance first, card charge for shortfall). Transfers net amount to affiliate via Stripe Connect (80/20 split).
19	class CommissionPayoutService
20	{
21	    private StripeClient $stripe;
22	
23	    private float $platformFeePercent;
24	
25	    private int $systemHoldDays;
26	
27	    private int $minHoldDays;
28	
29	    public function __construct(?StripeClient $stripe = null)
30	    {
31	        $this->stripe = $stripe ?? new StripeClient(config('services.stripe.secret_key'));
32	        $this->platformFeePercent = config('sidest.store.platform_fee_percent', 3);
33	        $this->systemHoldDays = max(0, (int) config('sidest.store.payout_hold_days', 7));
34	        $this->minHoldDays = (int) config('sidest.store.min_payout_hold_days', 7);
35	    }
36	
37	    /**
38	     * Main entry point: find all eligible unpaid commissions, batch them,
39	     * and dispatch a per-payout job for each. Returns dispatch counts only —
40	     * actual results are reported per-job via Horizon.
41	     *
42	     * @return array{batches_dispatched: int, batches_created: int, batches_requeued: int}
43	     */
44	    public function processEligiblePayouts(): array
45	    {
46	        $stats = [
47	            'batches_dispatched' => 0,
48	            'batches_created' => 0,
49	            'batches_requeued' => 0,
50	        ];
51	
52	        // Re-dispatch any in-flight batches. ExecuteCommissionPayoutJob's idempotent
53	        // resume logic handles collecting/transferring states safely.
54	        $existingPending = CommissionPayout::query()
55	            ->whereIn('status', ['pending', 'collecting', 'transferring'])
56	            ->whereNull('processed_at')
57	            ->where('eligible_after', '<=', now())
58	            ->orderBy('eligible_after')
59	            ->limit(500)
60	            ->get();
61	
62	        foreach ($existingPending as $pendingPayout) {
63	            ExecuteCommissionPayoutJob::dispatch($pendingPayout->id);
64	            $stats['batches_dispatched']++;
65	            $stats['batches_requeued']++;
66	        }
67	
68	        // Find all brands that have unpaid approved accruals, then apply
69	        // per-brand hold days to determine which entries are eligible.
70	        $brandIds = CommissionLedgerEntry::query()
71	            ->whereNull('payout_id')
72	            ->where('entry_type', 'accrual')
73	            ->where('status', 'approved')
74	            ->distinct()
75	            ->pluck('brand_professional_id');
76	
77	        // Pre-load brand store settings for hold-day lookups.
78	        $brandSettings = BrandStoreSettings::query()
79	            ->whereIn('professional_id', $brandIds)
80	            ->pluck('payout_hold_days', 'professional_id');
81	
82	        foreach ($brandIds as $brandId) {
83	            $holdDays = $this->resolveHoldDays($brandSettings[$brandId] ?? null);
84	            $cutoff = now()->utc()->subDays($holdDays);
85	
86	            $groups = CommissionLedgerEntry::query()
87	                ->whereNull('payout_id')
88	                ->where('entry_type', 'accrual')
89	                ->where('status', 'approved')
90	                ->where('brand_professional_id', $brandId)
91	                ->where('occurred_at', '<=', $cutoff)
92	                ->select([
93	                    'brand_professional_id',
94	                    'affiliate_professional_id',
95	                    'currency_code',
96	                    DB::raw('SUM(amount_cents) as total_cents'),
97	                    DB::raw('COUNT(*) as entry_count'),
98	                ])
99	                ->groupBy('brand_professional_id', 'affiliate_professional_id', 'currency_code')
100	                ->having(DB::raw('SUM(amount_cents)'), '>', 0)
101	                ->get();
102	
103	            foreach ($groups as $group) {
104	                try {
105	                    $payout = $this->createPayoutBatch(
106	                        $group->brand_professional_id,
107	                        $group->affiliate_professional_id,
108	                        $group->currency_code,
109	                        $cutoff,
110	                    );
111	
112	                    if (! $payout) {
113	                        continue;
114	                    }
115	
116	                    $stats['batches_created']++;
117	                    ExecuteCommissionPayoutJob::dispatch($payout->id);
118	                    $stats['batches_dispatched']++;
119	                } catch (\Throwable $e) {
120	                    Log::error('Commission payout batch creation failed', [
121	                        'brand_id' => $group->brand_professional_id,
122	                        'affiliate_id' => $group->affiliate_professional_id,
123	                        'currency' => $group->currency_code,
124	                        'error' => $e->getMessage(),
125	                    ]);
126	                }
127	            }
128	        }
129	
130	        return $stats;
131	    }
132	
133	    /**
134	     * Resolve the effective hold days for a brand.
135	     * Uses brand override if set, otherwise system default. Always >= system minimum.
136	     */
137	    private function resolveHoldDays(?int $brandPayoutHoldDays): int
138	    {
139	        $days = $brandPayoutHoldDays ?? $this->systemHoldDays;
140	
141	        return max($this->minHoldDays, $days);
142	    }
143	
144	    /**
145	     * Create a payout batch record and link all eligible ledger entries.
146	     */
147	    private function createPayoutBatch(
148	        string $brandId,
149	        string $affiliateId,
150	        string $currency,
151	        \DateTimeInterface $cutoff,
152	    ): ?CommissionPayout {
153	        return DB::transaction(function () use ($brandId, $affiliateId, $currency, $cutoff) {
154	            $entries = CommissionLedgerEntry::query()
155	                ->whereNull('payout_id')
156	                ->where('entry_type', 'accrual')
157	                ->where('status', 'approved')
158	                ->where('brand_professional_id', $brandId)
159	                ->where('affiliate_professional_id', $affiliateId)
160	                ->where('currency_code', $currency)
161	                ->where('occurred_at', '<=', $cutoff)
162	                ->lockForUpdate()
163	                ->get();
164	
165	            if ($entries->isEmpty()) {
166	                return null;
167	            }
168	
169	            $grossCents = $entries->sum('amount_cents');
170	            if ($grossCents <= 0) {
171	                return null;
172	            }
173	
174	            // Single locked fetch — reused for both the net-commission sum
175	            // below and the foreach that links these entries to the payout.
176	            // lockForUpdate matches the accrual fetch above and closes the
177	            // race where a reversal could land between SUM and GET.
178	            $reversals = CommissionLedgerEntry::query()
179	                ->whereNull('payout_id')
180	                ->where('entry_type', 'reversal')
181	                ->where('status', 'approved')
182	                ->where('brand_professional_id', $brandId)
183	                ->where('affiliate_professional_id', $affiliateId)
184	                ->where('currency_code', $currency)
185	                ->where('occurred_at', '<=', $cutoff)
186	                ->lockForUpdate()
187	                ->get();
188	
189	            $reversalCents = (int) $reversals->sum('amount_cents');
190	            $netCommission = $grossCents + $reversalCents;
191	            if ($netCommission <= 0) {
192	                return null;
193	            }
194	
195	            $platformFeeCents = (int) round($netCommission * $this->platformFeePercent / 100);
196	            $netPayoutCents = $netCommission - $platformFeeCents;
197	
198	            if ($netPayoutCents <= 0) {
199	                return null;
200	            }
201	
202	            // Per-payout grace window — 60d from creation. If the affiliate
203	            // hasn't activated Stripe Connect by then, VoidExpiredPayoutsJob
204	            // cancels this payout and voids its ledger entries.
205	            // grace_period_days lives in config/sidest.php so ops can tune
206	            // the policy without a code release.
207	            $graceDays = (int) config('sidest.store.grace_period_days', 60);
208	
209	            $payout = CommissionPayout::create([
210	                'brand_professional_id' => $brandId,
211	                'affiliate_professional_id' => $affiliateId,
212	                'status' => 'pending',
213	                'gross_commission_cents' => $netCommission,
214	                'platform_fee_cents' => $platformFeeCents,
215	                'net_payout_cents' => $netPayoutCents,
216	                'currency_code' => strtoupper($currency),
217	                'ledger_entry_count' => $entries->count(),
218	                'eligible_after' => $cutoff,
219	                'void_at' => now()->addDays($graceDays),
220	                'funding_source' => null,
221	            ]);
222	
223	            foreach ($entries as $entry) {
224	                CommissionPayoutItem::create([
225	                    'payout_id' => $payout->id,
226	                    'commission_ledger_entry_id' => $entry->id,
227	                    'amount_cents' => $entry->amount_cents,
228	                ]);
229	                $entry->update(['payout_id' => $payout->id]);
230	            }
231	
232	            foreach ($reversals as $reversal) {
233	                CommissionPayoutItem::create([
234	                    'payout_id' => $payout->id,
235	                    'commission_ledger_entry_id' => $reversal->id,
236	                    'amount_cents' => $reversal->amount_cents,
237	                ]);
238	                $reversal->update(['payout_id' => $payout->id]);
239	            }
240	
241	            return $payout;
242	        });
243	    }
244	
245	    /**
246	     * Process a single payout through the full 3-step flow with idempotent resume:
247	     *   1) Debit wallet balance (atomic with status update — crash-safe).
248	     *   2) Charge brand's card for any shortfall.
249	     *   3) Transfer net amount to affiliate via Stripe Connect.
250	     *
251	     * Each step checks the payout's current status before executing, so retries
252	     * (both Horizon automatic and admin manual) resume from where they left off
253	     * rather than restarting from scratch. This prevents double-debiting the wallet
254	     * and double-charging the brand's card.
255	     *
256	     * Return values:
257	     * - true:  completed
258	     * - null:  pending for funding/retry
259	     * - false: failed
260	     */
261	    public function processPayoutBatch(CommissionPayout $payout): ?bool
262	    {
263	        if ($payout->status === 'completed') {
264	            return true;
265	        }
266	
267	        $brand = Professional::find($payout->brand_professional_id);
268	        $affiliate = Professional::find($payout->affiliate_professional_id);
269	
270	        if (! $affiliate?->stripe_connect_account_id || $affiliate->stripe_connect_status !== 'active') {
271	            $this->markPendingFunding($payout, 'affiliate_not_connected', 'Affiliate Stripe Connect account is not active — holding for grace period');
272	
273	            return null;
274	        }
275	
276	        if (! $brand) {
277	            $this->failPayout($payout, 'brand_missing', 'Brand account was not found.');
278	
279	            return false;
280	        }
281	
282	        if (! $brand->stripe_customer_id || ! $brand->stripe_payment_method_id) {
283	            $this->markPendingFunding(
284	                $payout,
285	                'brand_payment_method_missing',
286	                'No payment method on file. Please add a card in your Stripe settings.',
287	            );
288	
289	            return null;
290	        }
291	
292	        $currencyUpper = strtoupper($payout->currency_code);
293	        $currencyLower = strtolower($currencyUpper);
294	        $amountToCollect = $payout->gross_commission_cents;
295	
296	        // Idempotency key suffix — retry_count is incremented on each admin manual retry
297	        // so fresh Stripe objects are created rather than returning a refunded/failed one
298	        // from within the 24-hour idempotency TTL window.
299	        $retryKey = '_r'.$payout->retry_count;
300	
301	        // Step 1: Wallet debit — or resume from recorded state
302	        //
303	        // The debit and the status update are wrapped in a single DB::transaction
304	        // so a process crash between them can't leave the wallet reduced but the
305	        // payout record still showing 'pending' (which would cause a double-debit on retry).
306	        $walletDebitCents = 0;
307	        $chargeAmountCents = $amountToCollect;
308	
309	        if (in_array($payout->status, ['collecting', 'collected', 'transferring'], true)) {
310	            // Wallet debit already committed in a previous run — read from DB, don't re-debit.
311	            $walletDebitCents = (int) ($payout->wallet_debit_cents ?? 0);
312	            $chargeAmountCents = (int) ($payout->charge_cents ?? $amountToCollect);
313	        } else {
314	            DB::transaction(function () use ($payout, $brand, $amountToCollect, $currencyUpper, &$walletDebitCents, &$chargeAmountCents): void {
315	                $walletDebitCents = $this->debitBrandManualBalancePartial($brand->id, $amountToCollect, $currencyUpper);
316	                $chargeAmountCents = $amountToCollect - $walletDebitCents;
317	
318	                $fundingSource = 'card';
319	                if ($walletDebitCents > 0 && $chargeAmountCents > 0) {
320	                    $fundingSource = 'wallet_and_card';
321	                } elseif ($walletDebitCents > 0) {
322	                    $fundingSource = 'wallet';
323	                }
324	
325	                $payout->update([
326	                    'status' => 'collecting',
327	                    'funding_source' => $fundingSource,
328	                    'wallet_debit_cents' => $walletDebitCents,
329	                    'charge_cents' => $chargeAmountCents,
330	                    'failure_code' => null,
331	                    'failure_reason' => null,
332	                ]);
333	            });
334	        }
335	
336	        // Step 2: Charge brand's card for the shortfall (if any)
337	        $latestChargeId = null;
338	
339	        if (in_array($payout->status, ['collected', 'transferring'], true)) {
340	            // PaymentIntent already succeeded in a previous run.
341	            // Retrieve the charge ID so we can use source_transaction on the transfer.
342	            if ($payout->stripe_payment_intent_id && $chargeAmountCents > 0) {
343	                $pi = $this->stripe->paymentIntents->retrieve($payout->stripe_payment_intent_id);
344	                $latestChargeId = $this->extractLatestChargeId($pi);
345	            }
346	        } elseif ($chargeAmountCents > 0) {
347	            try {
348	                $paymentIntent = $this->stripe->paymentIntents->create([
349	                    'amount' => $chargeAmountCents,
350	                    'currency' => $currencyLower,
351	                    'customer' => $brand->stripe_customer_id,
352	                    'payment_method' => $brand->stripe_payment_method_id,
353	                    'confirm' => true,
354	                    'off_session' => true,
355	                    'description' => "Commission payout #{$payout->id}",
356	                    'metadata' => [
357	                        'sidest_payout_id' => $payout->id,
358	                        'brand_id' => $brand->id,
359	                        'affiliate_id' => $affiliate->id,
360	                    ],
361	                ], ['idempotency_key' => 'pi_'.$payout->id.$retryKey]);
362	
363	                if ($paymentIntent->status !== 'succeeded') {
364	                    // SCA required — cancel the PI so the idempotency key is freed for the next
365	                    // attempt. Without cancellation the same key returns this stuck PI for 24h.
366	                    try {
367	                        $this->stripe->paymentIntents->cancel($paymentIntent->id);
368	                    } catch (\Throwable) {
369	                        // Non-critical: PI may already be in a terminal state
370	                    }
371	                    if ($walletDebitCents > 0) {
372	                        $this->creditBrandManualBalance($brand->id, $walletDebitCents, $currencyUpper);
373	                    }
374	                    $this->markPendingFunding($payout, 'charge_requires_action', 'Card charge requires authentication.');
375	
376	                    return null;
377	                }
378	
379	                $latestChargeId = $this->extractLatestChargeId($paymentIntent);
380	
381	                $payout->update([
382	                    'stripe_payment_intent_id' => $paymentIntent->id,
383	                    'status' => 'collected',
384	                ]);
385	            } catch (ApiConnectionException|RateLimitException $e) {
386	                // Transient error — re-throw so Horizon retries with backoff.
387	                // Wallet debit is already committed in 'collecting' status; the
388	                // idempotent resume will skip re-debiting on the next attempt.
389	                throw $e;
390	            } catch (ApiErrorException $e) {
391	                // Terminal card failure (declined, invalid PM, SCA permanently blocked, etc.)
392	                if ($walletDebitCents > 0) {
393	                    $this->creditBrandManualBalance($brand->id, $walletDebitCents, $currencyUpper);
394	                }
395	                $this->markPendingFunding($payout, 'charge_failed', $e->getMessage());
396	
397	                return null;
398	            }
399	        } else {
400	            // Fully funded by wallet — only advance status if not already past this step
401	            if (! in_array($payout->status, ['collected', 'transferring'], true)) {
402	                $payout->update(['status' => 'collected']);
403	            }
404	        }
405	
406	        // Step 3: Transfer net amount to the affiliate's Connect account
407	        try {
408	            if ($payout->status !== 'transferring') {
409	                $payout->update(['status' => 'transferring']);
410	            }
411	
412	            $transferPayload = [
413	                'amount' => $payout->net_payout_cents,
414	                'currency' => $currencyLower,
415	                'destination' => $affiliate->stripe_connect_account_id,
416	                'description' => "Commission payout #{$payout->id} to {$affiliate->display_name}",
417	                'metadata' => [
418	                    'sidest_payout_id' => $payout->id,
419	                    'brand_id' => $brand->id,
420	                    'affiliate_id' => $affiliate->id,
421	                ],
422	            ];
423	
424	            if ($latestChargeId) {
425	                $transferPayload['source_transaction'] = $latestChargeId;
426	            }
427	
428	            $transfer = $this->stripe->transfers->create(
429	                $transferPayload,
430	                ['idempotency_key' => 'tr_'.$payout->id.$retryKey]
431	            );
432	
433	            $payout->update([
434	                'stripe_transfer_id' => $transfer->id,
435	                'status' => 'completed',
436	                'processed_at' => now(),
437	                'failure_code' => null,
438	                'failure_reason' => null,
439	            ]);
440	
441	            Log::info('Commission payout completed', [
442	                'payout_id' => $payout->id,
443	                'gross_cents' => $payout->gross_commission_cents,
444	                'wallet_debit_cents' => $walletDebitCents,
445	                'charge_cents' => $chargeAmountCents,
446	                'platform_fee_cents' => $payout->platform_fee_cents,
447	                'net_cents' => $payout->net_payout_cents,
448	                'funding_source' => $payout->funding_source,
449	                'currency' => $payout->currency_code,
450	            ]);
451	
452	            // Rebuild commerce aggregates so commission_paid_cents is reflected.
453	            // Guard against null FKs (SET NULL on professional hard-delete).
454	            if ($payout->brand_professional_id && $payout->affiliate_professional_id) {
455	                \App\Jobs\Analytics\RebuildCommerceDailyAggregatesJob::dispatch(
456	                    (string) $payout->brand_professional_id,
457	                    (string) $payout->affiliate_professional_id,
458	                    now()->toDateString()
459	                );
460	            }
461	
462	            return true;
463	        } catch (ApiConnectionException|RateLimitException $e) {
464	            // Transient error — re-throw so Horizon retries from 'transferring' status.
465	            // Wallet and charge are NOT reversed: if the transfer succeeded on Stripe's side
466	            // but the response was lost in transit, the idempotency key returns the same
467	            // transfer on retry rather than creating a duplicate.
468	            throw $e;
469	        } catch (ApiErrorException $e) {
470	            // Terminal transfer failure — credit wallet back, then attempt to auto-refund.
471	            if ($walletDebitCents > 0) {
472	                $this->creditBrandManualBalance($brand->id, $walletDebitCents, $currencyUpper);
473	            }
474	
475	            $failureCode = 'transfer_failed';
476	
477	            if ($payout->stripe_payment_intent_id && $chargeAmountCents > 0) {
478	                try {
479	                    $this->stripe->refunds->create([
480	                        'payment_intent' => $payout->stripe_payment_intent_id,
481	                    ], ['idempotency_key' => "rf_{$payout->id}_{$payout->stripe_payment_intent_id}"]);
482	                    $failureCode = 'transfer_failed_refunded';
483	                    // Clear PI ID so an admin retry can create a fresh PaymentIntent
484	                    // (same idempotency key within 24h would return the now-refunded PI).
485	                    $payout->update(['stripe_payment_intent_id' => null]);
486	                } catch (\Throwable $refundEx) {
487	                    // Auto-refund failed — the brand may still be charged. Flag for manual resolution.
488	                    $failureCode = 'transfer_failed_refund_needed';
489	                    Log::error('Auto-refund after transfer failure failed — manual action required', [
490	                        'payout_id' => $payout->id,
491	                        'payment_intent_id' => $payout->stripe_payment_intent_id,
492	                        'transfer_error' => $e->getMessage(),
493	                        'refund_error' => $refundEx->getMessage(),
494	                    ]);
495	                }
496	            }
497	
498	            $this->failPayout($payout, $failureCode, $e->getMessage());
499	
500	            return false;
501	        }
502	    }
