504	    /**
505	     * Debit the brand's wallet balance, up to the requested amount (partial OK).
506	     * Returns the actual amount debited (0 if no balance available).
507	     */
508	    private function debitBrandManualBalancePartial(string $brandId, int $requestedCents, string $currencyCode): int
509	    {
510	        if ($requestedCents <= 0) {
511	            return 0;
512	        }
513	
514	        return DB::transaction(function () use ($brandId, $requestedCents, $currencyCode) {
515	            $brand = Professional::query()
516	                ->whereKey($brandId)
517	                ->lockForUpdate()
518	                ->first();
519	
520	            if (! $brand) {
521	                return 0;
522	            }
523	
524	            $balance = max(0, (int) ($brand->stripe_manual_balance_cents ?? 0));
525	            $walletCurrency = strtoupper((string) ($brand->stripe_manual_balance_currency ?: $currencyCode));
526	
527	            if ($walletCurrency !== strtoupper($currencyCode) || $balance <= 0) {
528	                return 0;
529	            }
530	
531	            $debit = min($balance, $requestedCents);
532	            $brand->stripe_manual_balance_cents = $balance - $debit;
533	            $brand->save();
534	
535	            return $debit;
536	        });
537	    }
