539	    private function creditBrandManualBalance(string $brandId, int $amountCents, string $currencyCode): void
540	    {
541	        if ($amountCents <= 0) {
542	            return;
543	        }
544	
545	        DB::transaction(function () use ($brandId, $amountCents, $currencyCode) {
546	            $brand = Professional::query()
547	                ->whereKey($brandId)
548	                ->lockForUpdate()
549	                ->first();
550	
551	            if (! $brand) {
552	                return;
553	            }
554	
555	            $balance = (int) ($brand->stripe_manual_balance_cents ?? 0);
556	            $brand->stripe_manual_balance_cents = $balance + $amountCents;
557	            $brand->stripe_manual_balance_currency = strtoupper((string) ($brand->stripe_manual_balance_currency ?: $currencyCode));
558	            $brand->save();
559	        });
560	    }
