562	    private function extractLatestChargeId(object $paymentIntent): ?string
563	    {
564	        if (is_string($paymentIntent->latest_charge ?? null) && $paymentIntent->latest_charge !== '') {
565	            return $paymentIntent->latest_charge;
566	        }
567	
568	        if (is_object($paymentIntent->latest_charge ?? null) && is_string($paymentIntent->latest_charge->id ?? null)) {
569	            return $paymentIntent->latest_charge->id;
570	        }
571	
572	        if (is_object($paymentIntent->charges ?? null) && is_array($paymentIntent->charges->data ?? null)) {
573	            foreach ($paymentIntent->charges->data as $charge) {
574	                if (is_object($charge) && is_string($charge->id ?? null) && $charge->id !== '') {
575	                    return $charge->id;
576	                }
577	            }
578	        }
579	
580	        return null;
581	    }
