614	    /**
615	     * Manually retry a stuck payout batch (admin endpoint).
616	     *
617	     * Increments retry_count so a fresh Stripe idempotency key is used —
618	     * prevents Stripe returning a refunded/failed PI from within the 24h TTL window.
619	     *
620	     * Blocked for transfer_failed_refund_needed: the auto-refund itself failed, so
621	     * the brand may still be charged. Manual verification is required before retrying.
622	     *
623	     * Runs synchronously so the admin sees the result immediately.
624	     */
625	    public function retryPayout(CommissionPayout $payout): bool
626	    {
627	        if (! in_array($payout->status, ['failed', 'pending'], true)) {
628	            return false;
629	        }
630	
631	        // Auto-refund failed — manual verification required before retrying to avoid double-charging.
632	        if ($payout->failure_code === 'transfer_failed_refund_needed') {
633	            return false;
634	        }
635	
636	        // If the wallet was already debited in a previous run, resume from 'collecting'
637	        // so processPayoutBatch() enters its idempotent resume branch and skips
638	        // re-debiting. Resetting to 'pending' would bypass that branch and double-debit.
639	        $resumeStatus = ((int) ($payout->wallet_debit_cents ?? 0)) > 0 ? 'collecting' : 'pending';
640	
641	        $payout->update([
642	            'status' => $resumeStatus,
643	            'failure_code' => null,
644	            'failure_reason' => null,
645	            'retry_count' => ($payout->retry_count ?? 0) + 1,
646	        ]);
647	
648	        return $this->processPayoutBatch($payout) === true;
649	    }
