651	    /**
652	     * Get payout summary for a professional (as brand or affiliate).
653	     */
654	    public function getPayoutSummary(Professional $professional): array
655	    {
656	        $asBrand = CommissionPayout::query()
657	            ->where('brand_professional_id', $professional->id)
658	            ->selectRaw('status, COUNT(*) as count, SUM(gross_commission_cents) as total_cents')
659	            ->groupBy('status')
660	            ->get()
661	            ->keyBy('status');
662	
663	        $asAffiliate = CommissionPayout::query()
664	            ->where('affiliate_professional_id', $professional->id)
665	            ->selectRaw('status, COUNT(*) as count, SUM(net_payout_cents) as total_cents')
666	            ->groupBy('status')
667	            ->get()
668	            ->keyBy('status');
669	
670	        return [
671	            'as_brand' => $asBrand,
672	            'as_affiliate' => $asAffiliate,
673	        ];
674	    }
