11	/**
12	 * Handles voiding commissions for affiliates who haven't connected Stripe.
13	 *
14	 * Two phases run on the daily cron:
15	 * 1. processVoidableCommissions() — void entries past their 30-day window
16	 * 2. sendGracePeriodWarnings() — nudge affiliates to connect Stripe
17	 *
18	 * Called from ProcessCommissionPayoutsJob after normal payout processing.
19	 */
20	class CommissionVoidService
21	{
22	    private int $voidWindowDays;
23	
24	    private int $gracePeriodDays;
25	
26	    public function __construct(private readonly NotificationPublisher $publisher)
27	    {
28	        $this->voidWindowDays = (int) config('sidest.store.commission_void_window_days', 30);
29	        $this->gracePeriodDays = (int) config('sidest.store.grace_period_days', 30);
30	    }
31	
32	    /**
33	     * Find and void all pending commissions past their void window
34	     * for affiliates without active Stripe accounts.
35	     *
36	     * @return array{voided_count: int, voided_cents: int}
37	     */
38	    public function processVoidableCommissions(): array
39	    {
40	        $cutoff = now()->subDays($this->voidWindowDays);
41	        $stats = ['voided_count' => 0, 'voided_cents' => 0];
42	
43	        // Chunk to avoid OOM on large result sets. Each entry is voided with
44	        // an optimistic lock so a concurrent flush won't be overwritten.
45	        CommissionLedgerEntry::query()
46	            ->whereNull('payout_id')
47	            ->where('entry_type', 'accrual')
48	            ->where('status', 'pending')
49	            ->where('occurred_at', '<=', $cutoff)
50	            ->whereHas('affiliateProfessional', function ($q) {
51	                $q->where('stripe_connect_status', '!=', 'active');
52	            })
53	            ->chunkById(500, function ($entries) use (&$stats) {
54	                foreach ($entries as $entry) {
55	                    try {
56	                        if ($this->voidEntry($entry, 'no_stripe_connected')) {
57	                            $stats['voided_count']++;
58	                            $stats['voided_cents'] += $entry->amount_cents;
59	                        }
60	                    } catch (\Throwable $e) {
61	                        Log::error('Failed to void commission entry', [
62	                            'entry_id' => $entry->id,
63	                            'error' => $e->getMessage(),
64	                        ]);
65	                    }
66	                }
67	            });
68	
69	        if ($stats['voided_count'] > 0) {
70	            Log::info('Commission void processing complete', $stats);
71	        }
72	
73	        return $stats;
74	    }
75	
76	    /**
77	     * Void a single commission entry. Uses an optimistic lock (WHERE status = pending)
78	     * so a concurrent flush-to-approved from a Stripe webhook can't be overwritten.
79	     *
80	     * @return bool True if the entry was voided, false if it was already claimed.
81	     */
82	    public function voidEntry(CommissionLedgerEntry $entry, string $reason): bool
83	    {
84	        $updated = CommissionLedgerEntry::query()
85	            ->where('id', $entry->id)
86	            ->where('status', 'pending')
87	            ->whereNull('payout_id')
88	            ->update([
89	                'status' => 'voided',
90	                'voided_at' => now(),
91	                'void_reason' => $reason,
92	            ]);
93	
94	        if ($updated === 0) {
95	            Log::info('Skipped voiding commission — status changed concurrently', [
96	                'entry_id' => $entry->id,
97	            ]);
98	
99	            return false;
100	        }
101	
102	        return true;
103	    }
104	
105	    /**
106	     * Send warning notifications to affiliates approaching void deadlines.
107	     *
108	     * Grace period warnings (day 20 and day 28 after signup):
109	     *   Sent to affiliates still within their grace period who haven't connected.
110	     *
111	     * Per-commission warnings (5 days before void window expires):
112	     *   Sent to post-grace affiliates for each commission about to void.
113	     *
114	     * @return array{warnings_sent: int}
115	     */
116	    public function sendGracePeriodWarnings(): array
117	    {
118	        $stats = ['warnings_sent' => 0];
119	
120	        $stats['warnings_sent'] += $this->sendSignupWarnings();
121	        $stats['warnings_sent'] += $this->sendPerCommissionWarnings();
122	
123	        return $stats;
124	    }
125	
126	    /**
127	     * Day 20 and day 28 warnings for affiliates in their initial grace period.
128	     */
129	    private function sendSignupWarnings(): int
130	    {
131	        $sent = 0;
132	
133	        // Collect affiliates in both warning windows (day 20 and day 28) then
134	        // batch-load their pending commission totals to avoid N+1 queries.
135	        $warningWindows = [
136	            'day20' => [
137	                'range' => [now()->addDays(9)->startOfDay(), now()->addDays(11)->endOfDay()],
138	                'title' => 'Connect Stripe — 10 days left',
139	                'body' => 'Connect your Stripe account within 10 days or your %s in pending earnings will be forfeited.',
140	            ],
141	            'day28' => [
142	                'range' => [now()->addDays(1)->startOfDay(), now()->addDays(3)->endOfDay()],
143	                'title' => 'Connect Stripe — 2 days left',
144	                'body' => '2 days left — connect Stripe now or your %s in pending earnings will be forfeited.',
145	            ],
146	        ];
147	
148	        foreach ($warningWindows as $key => $window) {
149	            Professional::query()
150	                ->whereIn('professional_type', ['influencer', 'professional'])
151	                ->where('stripe_connect_status', '!=', 'active')
152	                ->whereNotNull('stripe_grace_period_ends_at')
153	                ->where('stripe_grace_period_ends_at', '>', now())
154	                ->whereBetween('stripe_grace_period_ends_at', $window['range'])
155	                ->chunkById(200, function ($affiliates) use (&$sent, $key, $window) {
156	                    // Batch-load pending amounts for the chunk to avoid N+1
157	                    $pendingAmounts = $this->getPendingCommissionCentsBatch(
158	                        $affiliates->pluck('id')->all()
159	                    );
160	
161	                    foreach ($affiliates as $affiliate) {
162	                        $amount = $pendingAmounts[$affiliate->id] ?? 0;
163	                        if ($amount <= 0) {
164	                            continue;
165	                        }
166	
167	                        $this->publisher->publish(
168	                            professionalId: $affiliate->id,
169	                            frontendType: 'Warning',
170	                            category: 'commissions',
171	                            title: $window['title'],
172	                            body: sprintf($window['body'], $this->formatMoney($amount, 'AUD')),
173	                            dedupeKey: "stripe_warning.{$key}.{$affiliate->id}",
174	                            ctaUrl: '/account/settings?section=stripe',
175	                            retentionConfigKey: 'commission',
176	                        );
177	                        $sent++;
178	                    }
179	                });
180	        }
181	
182	        return $sent;
183	    }
184	
185	    /**
186	     * Per-commission warning: 5 days before each commission's void window.
187	     * For affiliates who are past their initial grace period.
188	     */
189	    private function sendPerCommissionWarnings(): int
190	    {
191	        $sent = 0;
192	        $warningCutoff = now()->addDays(5);
193	        $voidWindowDays = $this->voidWindowDays;
194	
195	        // Chunk to avoid OOM on large result sets.
196	        CommissionLedgerEntry::query()
197	            ->whereNull('payout_id')
198	            ->where('entry_type', 'accrual')
199	            ->where('status', 'pending')
200	            ->where('occurred_at', '<=', $warningCutoff->copy()->subDays($voidWindowDays))
201	            ->whereHas('affiliateProfessional', function ($q) {
202	                $q->where('stripe_connect_status', '!=', 'active')
203	                    ->where(function ($q2) {
204	                        $q2->whereNull('stripe_grace_period_ends_at')
205	                            ->orWhere('stripe_grace_period_ends_at', '<=', now());
206	                    });
207	            })
208	            ->with('affiliateProfessional:id,display_name')
209	            ->chunkById(500, function ($entries) use (&$sent, $voidWindowDays) {
210	                foreach ($entries as $entry) {
211	                    $voidDate = $entry->occurred_at->addDays($voidWindowDays);
212	                    $daysLeft = (int) now()->diffInDays($voidDate, false);
213	
214	                    if ($daysLeft < 0 || $daysLeft > 5) {
215	                        continue;
216	                    }
217	
218	                    $this->publisher->publish(
219	                        professionalId: $entry->affiliate_professional_id,
220	                        frontendType: 'Warning',
221	                        category: 'commissions',
222	                        title: 'Commission expiring soon',
223	                        body: sprintf(
224	                            'Connect Stripe within %d days or your %s commission from %s will be forfeited.',
225	                            $daysLeft,
226	                            $this->formatMoney($entry->amount_cents, $entry->currency_code),
227	                            $entry->occurred_at->format('M j'),
228	                        ),
229	                        dedupeKey: "stripe_warning.commission.{$entry->id}",
230	                        ctaUrl: '/account/settings?section=stripe',
231	                        retentionConfigKey: 'commission',
232	                    );
233	                    $sent++;
234	                }
235	            });
236	
237	        return $sent;
238	    }
