283	     * @return array<string, int> affiliate_id => total_pending_cents
284	     */
285	    /**
286	     * Voids up to $cap pending commission entries for a specific affiliate-brand pair.
287	     * Returns overflow: true (without voiding) when count exceeds cap — caller should
288	     * dispatch VoidPendingCommissionsForLinkJob instead.
289	     *
290	     * @return array{count: int, total_cents: int, overflow: bool}
291	     */
292	    public function voidPendingForAffiliateBrand(
293	        string $affiliateProfessionalId,
294	        string $brandProfessionalId,
295	        string $reason,
296	        int $cap = 200,
297	    ): array {
298	        $pendingCount = DB::table('commerce.commission_ledger_entries')
299	            ->where('affiliate_professional_id', $affiliateProfessionalId)
300	            ->where('brand_professional_id', $brandProfessionalId)
301	            ->where('status', 'pending')
302	            ->whereNull('payout_id')
303	            ->count();
304	
305	        if ($pendingCount > $cap) {
306	            return ['count' => 0, 'total_cents' => 0, 'overflow' => true];
307	        }
